<script setup lang="ts">import{onMounted,ref}from'vue';import{API,getJSON}from'../services/api';const figs=ref<string[]>([]);onMounted(async()=>{try{figs.value=(await getJSON('/figures/list')).figures}catch{}})</script><template><section class="panel"><h2>Model & Data Figures</h2><div class="gallery"><figure v-for="f in figs"><img :src="`${API}/figures/${f}`"/><figcaption>{{f.replaceAll('_',' ').replace('.png','')}}</figcaption></figure></div></section></template>